WITH parsed AS (SELECT id, service, host, log_ts, level, latency_ms, payload_json, SHIFTRIGHT(status_code, 2) AS status_code_high, context['version'] AS version, COALESCE(context['version'], 'none') AS version_or_default, GET_JSON_OBJECT(payload_json, '$.user.tier') AS user_tier FROM app_logs) SELECT id, level, latency_ms, status_code_high, version_or_default, user_tier, SUM(latency_ms) OVER (PARTITION BY host ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_sum_latency_ms, MIN(latency_ms) OVER (PARTITION BY host ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_min_latency_ms, MAX(latency_ms) OVER (PARTITION BY host ORDER BY log_ts, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_max_latency_ms, PERCENT_RANK() OVER (ORDER BY status_code_high DESC NULLS FIRST) AS status_code_high_percent_rank FROM parsed;
